CREATE TABLE alerts (
	id INTEGER NOT NULL, 
	alert_id VARCHAR(100) NOT NULL, 
	alert_type VARCHAR(50) NOT NULL, 
	severity VARCHAR(20) NOT NULL, 
	entity_id VARCHAR(100), 
	message TEXT NOT NULL, 
	details_json TEXT, 
	is_acknowledged BOOLEAN NOT NULL, 
	acknowledged_at DATETIME, 
	acknowledged_by VARCHAR(100), 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, user_id INTEGER, customer_id VARCHAR(100), title VARCHAR(200), status VARCHAR(50) DEFAULT 'OPEN', resolved_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE audit_logs (
	id INTEGER NOT NULL, 
	user_id INTEGER, 
	action VARCHAR(100) NOT NULL, 
	resource_type VARCHAR(100) NOT NULL, 
	resource_id VARCHAR(100), 
	details TEXT, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, entity VARCHAR(100), entity_id VARCHAR(100), ip_address VARCHAR(50), device_id VARCHAR(100), result VARCHAR(50) DEFAULT 'SUCCESS', 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL
);
CREATE TABLE behavioral_profiles (
	id INTEGER NOT NULL, 
	user_id INTEGER, 
	customer_id VARCHAR(100) NOT NULL, 
	normal_transaction_range VARCHAR(100) NOT NULL, 
	normal_transaction_frequency VARCHAR(100) NOT NULL, 
	common_transaction_times VARCHAR(150) NOT NULL, 
	common_locations TEXT NOT NULL, 
	trusted_devices TEXT NOT NULL, 
	average_transaction_amount FLOAT NOT NULL, 
	behavioral_baseline TEXT, 
	security_score INTEGER NOT NULL, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
CREATE TABLE beneficiaries (
	id INTEGER NOT NULL, 
	customer_id VARCHAR(100) NOT NULL, 
	beneficiary_name VARCHAR(150) NOT NULL, 
	beneficiary_account VARCHAR(100), 
	category VARCHAR(50) NOT NULL, 
	trust_score FLOAT NOT NULL, 
	is_trusted BOOLEAN NOT NULL, 
	total_transfers INTEGER NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	last_used_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id) ON DELETE CASCADE
);
CREATE TABLE customer_devices (
	id INTEGER NOT NULL, 
	customer_id VARCHAR(100) NOT NULL, 
	device_identifier VARCHAR(150) NOT NULL, 
	device_type VARCHAR(50) NOT NULL, 
	browser_or_client VARCHAR(100), 
	location_region VARCHAR(100), 
	is_trusted BOOLEAN NOT NULL, 
	is_compromised BOOLEAN NOT NULL, 
	first_seen_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	last_seen_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, user_id INTEGER, device_name VARCHAR(150), os VARCHAR(100), browser VARCHAR(100), trust_score INTEGER DEFAULT 100, status VARCHAR(50) DEFAULT 'ACTIVE', 
	PRIMARY KEY (id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id) ON DELETE CASCADE
);
CREATE TABLE customers (
	id INTEGER NOT NULL, 
	customer_id VARCHAR(100) NOT NULL, 
	account_age_days INTEGER, 
	simulated_balance FLOAT DEFAULT '50000.0' NOT NULL, 
	currency VARCHAR(10) DEFAULT 'USD' NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	name VARCHAR(200), 
	email VARCHAR(200), 
	risk_segment VARCHAR(50), 
	PRIMARY KEY (id)
);
CREATE TABLE idempotency_records (
	id INTEGER NOT NULL, 
	idempotency_key VARCHAR(128) NOT NULL, 
	request_fingerprint VARCHAR(64) NOT NULL, 
	resource_id VARCHAR(100), 
	status_code INTEGER NOT NULL, 
	response_json TEXT NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	expires_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE investigations (
	id INTEGER NOT NULL, 
	case_id VARCHAR(100) NOT NULL, 
	transaction_id VARCHAR(100) NOT NULL, 
	investigator_id INTEGER, 
	status VARCHAR(50) NOT NULL, 
	decision VARCHAR(50), 
	notes TEXT, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(transaction_id) REFERENCES transactions (transaction_id) ON DELETE CASCADE, 
	FOREIGN KEY(investigator_id) REFERENCES users (id) ON DELETE SET NULL
);
