CREATE TABLE merchants (
	id INTEGER NOT NULL, 
	merchant_id VARCHAR(50) NOT NULL, 
	merchant_name VARCHAR(150) NOT NULL, 
	category VARCHAR(100) NOT NULL, 
	subcategory VARCHAR(100), 
	city VARCHAR(100) NOT NULL, 
	area VARCHAR(150), 
	state VARCHAR(100), 
	pincode VARCHAR(20), 
	latitude FLOAT, 
	longitude FLOAT, 
	business_age INTEGER NOT NULL, 
	average_ticket FLOAT NOT NULL, 
	operating_hours VARCHAR(100), 
	business_type VARCHAR(100), 
	payment_channel VARCHAR(100), 
	historical_fraud_rate FLOAT NOT NULL, 
	historical_fraud_count INTEGER NOT NULL, 
	historical_fraud_pattern VARCHAR(200), 
	historical_fraud_summary TEXT, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE model_versions (
	id INTEGER NOT NULL, 
	model_name VARCHAR(100) NOT NULL, 
	version VARCHAR(50) NOT NULL, 
	accuracy FLOAT, 
	precision FLOAT, 
	recall FLOAT, 
	f1_score FLOAT, 
	roc_auc FLOAT, 
	pr_auc FLOAT, 
	model_path VARCHAR(500), 
	is_active BOOLEAN NOT NULL, 
	trained_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_model_version_name_ver UNIQUE (model_name, version)
);
CREATE TABLE payment_attempts (
	id INTEGER NOT NULL, 
	payment_id VARCHAR(100) NOT NULL, 
	attempt_number INTEGER NOT NULL, 
	provider_name VARCHAR(50) NOT NULL, 
	external_payment_id VARCHAR(100), 
	status VARCHAR(50) NOT NULL, 
	error_message TEXT, 
	error_type VARCHAR(50), 
	raw_response TEXT, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(payment_id) REFERENCES payment_intents (payment_id) ON DELETE CASCADE
);
CREATE TABLE payment_intents (
	id INTEGER NOT NULL, 
	payment_id VARCHAR(100) NOT NULL, 
	customer_id VARCHAR(100) NOT NULL, 
	amount FLOAT NOT NULL, 
	currency VARCHAR(10) NOT NULL, 
	merchant_name VARCHAR(150) NOT NULL, 
	merchant_category VARCHAR(50) NOT NULL, 
	payment_method VARCHAR(50) NOT NULL, 
	beneficiary_name VARCHAR(150), 
	lifecycle_status VARCHAR(50) NOT NULL, 
	is_new_beneficiary BOOLEAN, 
	is_new_device BOOLEAN, 
	fraud_probability FLOAT, 
	risk_score INTEGER, 
	risk_level VARCHAR(20), 
	fraud_decision VARCHAR(20), 
	behaviour_deviation_score FLOAT, 
	is_cold_start BOOLEAN, 
	model_version VARCHAR(50), 
	explanation_id VARCHAR(100), 
	provider_name VARCHAR(50) NOT NULL, 
	external_payment_id VARCHAR(100), 
	idempotency_key VARCHAR(128), 
	request_fingerprint VARCHAR(64), 
	case_id VARCHAR(100), 
	approval_id VARCHAR(100), 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id)
);
CREATE TABLE risk_events (
	id INTEGER NOT NULL, 
	user_id INTEGER, 
	customer_id VARCHAR(100), 
	transaction_id VARCHAR(100), 
	event_type VARCHAR(100) NOT NULL, 
	severity VARCHAR(20) NOT NULL, 
	score INTEGER NOT NULL, 
	explanation TEXT NOT NULL, 
	details_json TEXT, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
CREATE TABLE shap_explanations (
	id INTEGER NOT NULL, 
	transaction_id VARCHAR(100) NOT NULL, 
	feature_name VARCHAR(100) NOT NULL, 
	shap_value FLOAT NOT NULL, 
	impact VARCHAR(50), 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(transaction_id) REFERENCES transactions (transaction_id) ON DELETE CASCADE
);
