CREATE TABLE transaction_approvals (
	id INTEGER NOT NULL, 
	approval_id VARCHAR(100) NOT NULL, 
	payment_id VARCHAR(100), 
	transaction_id VARCHAR(100), 
	customer_id VARCHAR(100) NOT NULL, 
	user_id INTEGER, 
	status VARCHAR(50) NOT NULL, 
	amount FLOAT NOT NULL, 
	currency VARCHAR(10) NOT NULL, 
	risk_score INTEGER NOT NULL, 
	risk_level VARCHAR(20) NOT NULL, 
	fraud_probability FLOAT NOT NULL, 
	challenge_type VARCHAR(50) NOT NULL, 
	verification_token VARCHAR(100), 
	notes TEXT, 
	requested_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	responded_at DATETIME, 
	expires_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(payment_id) REFERENCES payment_intents (payment_id) ON DELETE CASCADE, 
	FOREIGN KEY(transaction_id) REFERENCES transactions (transaction_id) ON DELETE CASCADE, 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL
);
CREATE TABLE transactions (
	id INTEGER NOT NULL, 
	transaction_id VARCHAR(100) NOT NULL, 
	customer_id VARCHAR(100) NOT NULL, 
	merchant_id VARCHAR(50), 
	merchant_name VARCHAR(150), 
	merchant_category VARCHAR(100), 
	amount NUMERIC(14, 2) NOT NULL, 
	currency VARCHAR(10) NOT NULL, 
	transaction_hour INTEGER NOT NULL, 
	day_of_week INTEGER, 
	transaction_type VARCHAR(50), 
	payment_channel VARCHAR(50), 
	transaction_country VARCHAR(10), 
	geo_location_region VARCHAR(100), 
	current_location VARCHAR(150), 
	usual_location VARCHAR(150), 
	location_changed BOOLEAN, 
	location_distance FLOAT, 
	device_id VARCHAR(100), 
	device_type VARCHAR(50), 
	is_new_device BOOLEAN, 
	is_trusted_device BOOLEAN, 
	beneficiary VARCHAR(150), 
	beneficiary_id VARCHAR(100), 
	is_new_beneficiary BOOLEAN, 
	transactions_last_1h INTEGER, 
	transactions_last_24h INTEGER, 
	transactions_last_7d INTEGER, 
	amount_deviation FLOAT, 
	amount_ratio FLOAT, 
	failed_transaction_attempts INTEGER, 
	failed_login_attempts INTEGER, 
	recent_password_change BOOLEAN, 
	fraud_probability FLOAT, 
	prediction INTEGER, 
	risk_score FLOAT, 
	risk_level VARCHAR(20), 
	is_fraud INTEGER, 
	fraud_type VARCHAR(100), 
	fraud_stage VARCHAR(100), 
	fraud_scenario VARCHAR(150), 
	status VARCHAR(50), 
	approval_id VARCHAR(100), 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id) ON DELETE CASCADE, 
	FOREIGN KEY(merchant_id) REFERENCES merchants (merchant_id) ON DELETE SET NULL
);
CREATE TABLE user_sessions (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	customer_id VARCHAR(100), 
	session_id VARCHAR(100) NOT NULL, 
	device_id VARCHAR(150), 
	device_name VARCHAR(150), 
	ip_address VARCHAR(50), 
	approximate_location VARCHAR(150), 
	session_status VARCHAR(50) NOT NULL, 
	risk_score INTEGER NOT NULL, 
	login_time DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	last_active DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
CREATE TABLE users (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	email VARCHAR(255) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	role VARCHAR(50) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, account_tier VARCHAR(50) DEFAULT 'STANDARD', account_status VARCHAR(50) DEFAULT 'ACTIVE', 
	PRIMARY KEY (id)
);
CREATE TABLE verification_events (
	id INTEGER NOT NULL, 
	user_id INTEGER, 
	customer_id VARCHAR(100), 
	transaction_id VARCHAR(100), 
	verification_type VARCHAR(50) NOT NULL, 
	status VARCHAR(50) NOT NULL, 
	otp_code_hash VARCHAR(255), 
	attempts_count INTEGER NOT NULL, 
	max_attempts INTEGER NOT NULL, 
	expires_at DATETIME NOT NULL, 
	last_attempted_at DATETIME, 
	resend_available_at DATETIME, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	verified_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
